from pathlib import Path
import json
root=Path(__file__).resolve().parent
marks=[
 dict(id='block-b',name='Block B',tag='A name made recognisable.',description='A bold B built from three separate pieces. Direct, grounded and easy to recognise at a glance.',note='The strongest link to the Bigmints name.',body='<path d="M18 18H38V114H18Z"/><path fill-rule="evenodd" d="M46 18H77C97 18 110 29 110 43C110 57 97 62 79 62H46ZM64 34V48H77C85 48 91 46 91 41C91 36 85 34 77 34Z"/><path fill-rule="evenodd" d="M46 70H80C101 70 112 79 112 92C112 106 99 114 78 114H46ZM64 84V100H78C87 100 93 97 93 92C93 87 87 84 78 84Z"/>'),
 dict(id='mint-mosaic',name='Mint mosaic',tag='Many parts. One family.',description='Six curved tiles form a compact pattern. A subtle nod to mint leaves, with room for a growing family of products.',note='The closest fit to your pattern-led direction.',body=''.join(f'<g transform="translate({27+x*40} {10+y*38})"><path d="M0 0H10C23.25 0 34 10.75 34 24V34H24C10.75 34 0 23.25 0 10Z" transform="{("translate(34 0) scale(-1 1)" if (x+y)%2 else "")}"/></g>' for y in range(3) for x in range(2))),
 dict(id='open-frame',name='Open frame',tag='Make room for possibility.',description='An open path creates space within a structured frame. A quieter symbol for products that make everyday life easier.',note='The closest fit to “Make room for life.”',body='<path d="M106 20H49C32.98 20 20 32.98 20 49V108H79C95.02 108 108 95.02 108 79V48H57V79" fill="none" stroke="currentColor" stroke-width="17" stroke-linejoin="round" stroke-linecap="butt"/>')
]
def svg(m,cls=''):
 return f'<svg class="{cls}" viewBox="0 0 128 128" xmlns="http://www.w3.org/2000/svg" fill="currentColor" aria-hidden="true">{m["body"]}</svg>'
for m in marks:
 (root/(m['id']+'.svg')).write_text(svg(m))
cards=''
for i,m in enumerate(marks):
 cards+=f'''<article class="card" id="{m['id']}"><div class="card-top"><span>0{i+1}</span><span>{['LETTERFORM','MODULAR PATTERN','NEGATIVE SPACE'][i]}</span></div><div class="large-mark">{svg(m)}</div><div class="lockup">{svg(m)}<span>bigmints</span></div><h2>{m['name']}</h2><p class="tag">{m['tag']}</p><p class="description">{m['description']}</p><div class="applications"><div class="sizes">{svg(m,'tiny')}{svg(m,'small')}{svg(m,'medium')}</div><div class="app-icon">{svg(m)}</div></div><div class="pattern" aria-label="Repeating {m['name']} pattern">{''.join(svg(m) for _ in range(10))}</div><p class="note">{m['note']}</p><button class="select" data-choice="{i}" aria-pressed="{'true' if i==1 else 'false'}">Preview this direction <span>↗</span></button><a class="download" href="{m['id']}.svg" download>Download SVG ↓</a></article>'''
html='''<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Bigmints — Three identity directions</title><style>
@import url('https://fonts.googleapis.com/css2?family=DM+Sans:wght@400;450;500;600;650&family=Instrument+Serif&display=swap');
*{box-sizing:border-box}body{margin:0;background:#f4f4f2;color:#171717;font-family:'DM Sans',Arial,sans-serif;-webkit-font-smoothing:antialiased}.sheet{max-width:1500px;margin:auto;padding:44px 48px 36px}.eyebrow,.card-top{font-size:10px;letter-spacing:.13em;font-weight:500}.top{display:flex;justify-content:space-between;align-items:center;padding-bottom:23px;border-bottom:1px solid #d6d6d3}.top span:last-child{color:#70706b}h1{font-family:'Instrument Serif',Georgia,serif;font-size:58px;line-height:1.03;font-weight:400;letter-spacing:-.035em;margin:26px 0 16px}.intro{display:flex;justify-content:space-between;align-items:end;margin-bottom:32px;gap:30px}.intro p{max-width:470px;font-size:13px;line-height:1.7;color:#666;margin:0 0 3px}.grid{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:20px}.card{background:white;border:1px solid #d8d8d4;padding:24px 28px 18px}.card-top{display:flex;justify-content:space-between;color:#777}.large-mark{height:190px;display:grid;place-items:center}.large-mark svg{width:132px;height:132px}.lockup{display:flex;align-items:center;justify-content:center;gap:10px;padding-bottom:24px;border-bottom:1px solid #e5e5e1}.lockup svg{width:30px;height:30px}.lockup span{font-size:27px;letter-spacing:-.055em;font-weight:650}h2{font-size:27px;font-weight:450;letter-spacing:-.035em;margin:22px 0 6px}.tag{font-size:12px;font-weight:500;margin:0 0 11px}.description{font-size:12px;line-height:1.75;color:#70706a;min-height:63px;margin:0}.applications{display:flex;align-items:center;justify-content:space-between;padding:21px 0}.sizes{display:flex;align-items:center;gap:24px}.tiny{width:16px;height:16px}.small{width:24px;height:24px}.medium{width:36px;height:36px}.app-icon{display:grid;place-items:center;width:53px;height:53px;background:#171717;color:white;border-radius:13px}.app-icon svg{width:36px;height:36px}.pattern{height:62px;background:#f5f5f2;padding:7px 6px;display:grid;grid-template-columns:repeat(10,1fr);align-items:center;overflow:hidden;gap:1px}.pattern svg{width:100%;opacity:.72}.pattern svg:nth-child(even){opacity:.27;transform:translateY(7px)}.note{font-size:11px;color:#686862;line-height:1.5;margin:17px 0;min-height:32px}.select{display:flex;justify-content:space-between;width:100%;background:white;border:1px solid #ccc;padding:12px 13px;font:inherit;font-size:11px;cursor:pointer;color:#171717}.select[aria-pressed=true]{background:#171717;color:white;border-color:#171717}.select:hover{border-color:#171717}.download{display:block;text-align:center;color:#666;text-decoration:none;font-size:10px;margin-top:13px}.download:hover{text-decoration:underline}.foot{display:flex;justify-content:space-between;gap:20px;color:#777;font-size:10px;line-height:1.6;margin:24px 0 0}.preview-section{max-width:1500px;margin:30px auto 60px;padding:0 48px}.preview-controls{display:flex;align-items:center;justify-content:space-between;margin-bottom:18px}.preview-controls h2{font-size:19px;margin:0}.theme{background:transparent;border:1px solid #aaa;padding:10px 15px;font:inherit;font-size:11px;cursor:pointer}.preview{background:white;color:#171717;border:1px solid #ddd;padding:26px 34px}.preview.dark{background:#171717;color:white}.preview-header{display:flex;align-items:center;justify-content:space-between;border-bottom:1px solid #aaa5;padding-bottom:24px}.preview-lockup{display:flex;gap:10px;align-items:center;font-size:27px;font-weight:650;letter-spacing:-.055em}.preview-lockup svg{width:36px;height:36px}.nav{display:flex;gap:25px;font-size:11px}.preview-hero{display:grid;grid-template-columns:1.6fr 1fr;align-items:center;padding:50px 0 24px;gap:25px}.preview-hero h3{font-family:'Instrument Serif',Georgia,serif;font-weight:400;font-size:clamp(36px,4.3vw,67px);line-height:1.06;letter-spacing:-.03em;margin:0 0 22px}.preview-hero h3 em{font-style:normal;opacity:.5}.preview-hero p{font-size:13px;line-height:1.8;max-width:410px;opacity:.7}.hero-pattern{display:grid;grid-template-columns:repeat(3,1fr);gap:15px;max-width:290px;justify-self:end}.hero-pattern svg{width:100%}.hero-pattern svg:nth-child(3n+2){opacity:.45}.hero-pattern svg:nth-child(3n){opacity:.15}:focus-visible{outline:2px solid #666;outline-offset:4px}
@media(min-width:1500px){.sheet{padding-top:50px}.large-mark{height:210px}}@media(max-width:850px){.sheet{padding:25px 20px}.intro{display:block}.intro p{margin-top:20px}h1{font-size:44px}.grid{grid-template-columns:1fr}.card{padding:24px}.large-mark{height:170px}.description,.note{min-height:0}.pattern{grid-template-columns:repeat(10,1fr)}.preview-section{padding:0 20px}.preview{padding:24px}.nav{display:none}.preview-hero{grid-template-columns:1fr}.hero-pattern{max-width:190px;justify-self:start}.foot{display:block}.foot span{display:block;margin-top:7px}.preview-controls{gap:15px}.top span:last-child{font-size:8px;text-align:right}}
</style></head><body><main><section class="sheet"><header class="top"><span class="eyebrow">BIGMINTS / IDENTITY EXPLORATIONS</span><span class="eyebrow">01—03 &nbsp; / &nbsp; OCTOBER 2026</span></header><div class="intro"><h1>A mark of our own.</h1><p>Three directions for Bigmints. Black and white.<br>Each shown as a symbol, a signature, an app icon and a repeating pattern.</p></div><div class="grid">'''+cards+'''</div><footer class="foot"><span>Design explorations for Bigmints FZE LLC. The current website identity is unchanged.</span><span>Concept artwork • Trademark clearance pending</span></footer></section><section class="preview-section"><div class="preview-controls"><h2 id="preview-title" aria-live="polite">In context / Mint mosaic</h2><button class="theme" id="theme" aria-pressed="false">Switch to dark</button></div><div class="preview" id="preview"><div class="preview-header"><div class="preview-lockup" id="preview-lockup"></div><div class="nav"><span>Products</span><span>Company</span><span>Innovation</span><span>Get in touch ↗</span></div></div><div class="preview-hero"><div><h3>Make work easier.<br><em>Make room for life.</em></h3><p>From running a business to getting people together, our products make everyday things a little easier.</p></div><div class="hero-pattern" id="hero-pattern"></div></div></div></section></main><script>
const marks='''+json.dumps([dict(name=m['name'],svg=svg(m)) for m in marks])+''';
function choose(i){document.getElementById('preview-title').textContent='In context / '+marks[i].name;document.getElementById('preview-lockup').innerHTML=marks[i].svg+'<span>bigmints</span>';document.getElementById('hero-pattern').innerHTML=marks[i].svg.repeat(9);document.querySelectorAll('[data-choice]').forEach(b=>b.setAttribute('aria-pressed',String(+b.dataset.choice===i)));}document.querySelectorAll('[data-choice]').forEach(b=>b.addEventListener('click',()=>choose(+b.dataset.choice)));document.getElementById('theme').addEventListener('click',()=>{const dark=document.getElementById('preview').classList.toggle('dark');document.getElementById('theme').textContent=dark?'Switch to light':'Switch to dark';document.getElementById('theme').setAttribute('aria-pressed',String(dark));});choose(1);
</script></body></html>'''
(root/'index.html').write_text(html)
print('Created three SVG concepts and an interactive comparison page.')
